import {LabelLayout,polarCandidates,paintLabel} from './label-layout.js?v=18';
import {angleMark} from './angle-renderer.js?v=11';
const point=(c,a,r)=>({x:c.x+Math.cos(a)*r,y:c.y+Math.sin(a)*r});
export function layoutDiagram(q,width,height,measure=text=>text.length*7){const centre={x:width/2,y:height/2},radius=Math.min(width,height)*.32,arc=radius*.4;let best=null;
 for(let turn=0;turn<24;turn++){const rotation=(q.rotation+turn*15)*Math.PI/180,starts=[];let sum=0;for(const v of q.values){starts.push(sum*Math.PI/180);sum+=v;}const rays=starts.concat(q.total===180?[Math.PI]:[]).map(a=>point(centre,-a-rotation,radius)),layout=new LabelLayout(),regions=q.values.map((v,i)=>({p:centre,radius:arc,start:-starts[i]-rotation,sweep:-v*Math.PI/180}));layout.begin({bounds:{x:4,y:4,w:width-8,h:height-8},segments:rays.map(p=>[centre,p]),points:[centre],arcs:regions});let score=0;const labels=[];
 const order=q.labels.map((text,i)=>({text,i,width:measure(text)})).sort((a,b)=>b.width-a.width);
 for(const {text,i,width:w}of order){const r=regions[i],mid=r.start+r.sweep/2,candidates=polarCandidates(centre,mid,arc+17,{spread:Math.min(.18,Math.abs(r.sweep)/7),step:8,rings:10}),label=layout.place({id:String(i),text,width:w,height:13,candidates});const box=layout.placed.pop();score+=layout.score(label,w,13);layout.placed.push(box);labels.push({...label,index:i});}layout.end();const result={centre,radius,arc,rays,regions,labels,score};if(!best||score<best.score)best=result;if(score===0)break;
 }return best;}
export function drawQuestionDiagram(ctx,q,width,height){ctx.save();ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.font='13px WorksheetFont, sans-serif';const g=layoutDiagram(q,width,height,t=>ctx.measureText(t).width);if(g.score>0)throw Error('This diagram needs more room. Regenerate questions or choose fewer questions.');ctx.strokeStyle='#202124';ctx.fillStyle='#202124';ctx.lineWidth=1.3;for(const r of g.regions)angleMark(ctx,{...r,rightAngleDisplay:'marker-and-value'});for(const p of g.rays){ctx.beginPath();ctx.moveTo(g.centre.x,g.centre.y);ctx.lineTo(p.x,p.y);ctx.stroke();}ctx.beginPath();ctx.arc(g.centre.x,g.centre.y,2,0,Math.PI*2);ctx.fill();for(const label of g.labels)paintLabel(ctx,label,{ink:'#161616',background:'#fff'});ctx.restore();return g;}
export function diagramImage(q,wMM,hMM){const w=wMM*3.78,h=hMM*3.78,canvas=document.createElement('canvas');canvas.width=Math.ceil(w*3);canvas.height=Math.ceil(h*3);const ctx=canvas.getContext('2d');ctx.scale(3,3);drawQuestionDiagram(ctx,q,w,h);return canvas.toDataURL('image/png');}
